uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float flash_freq : 0.1 .. 10.0 = 2.0;
uniform float flash_size : 0.01 .. 0.5 = 0.15;
uniform vec3 tint : color = 0.9, 0.8, 0.7;
state fixed ph;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed));
}
vec3 shade(Led led) {
  fixed t = fixed(led.pos.y) / fixed(0.30);
  fixed cloudiness = smoothstep(fixed(0.7), fixed(0.3), t);
  fixed flash = sin(fixed(led.s) * fixed(6.283185307179586) * fixed(flash_freq) + ph) * fixed(0.5) + fixed(0.5);
  flash = clamp(fixed(0.0), fixed(0.0), flash) * flash_size;
  fixed flash_mask = step(fixed(0.0), fixed(led.s) - ph);
  return mix(vec3(0.0, 0.0, 0.0), tint, flash * cloudiness);
}
